import 'dart:convert';
import 'dart:io';

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:integration_test/integration_test.dart';
import 'package:path_provider/path_provider.dart';
import 'package:shared_preferences/shared_preferences.dart';
import 'package:opendocs/data/document_repository.dart';
import 'package:opendocs/data/document_thumbnails.dart';
import 'package:opendocs/data/reader_bookmarks.dart';
import 'package:opendocs/features/pdf_reader_screen.dart';
import 'package:opendocs/main.dart' as app;

void main() {
  final binding = IntegrationTestWidgetsFlutterBinding.ensureInitialized();
  testWidgets('PDF bookmarks, thumbnail pixels and safe native cache cleanup', (
    tester,
  ) async {
    final source = base64Decode(
      '',
    );
    const key = 'qa-reader-features';
    await ReaderBookmarks.save(key, []);
    await tester.pumpWidget(
      MaterialApp(
        home: PdfReaderScreen(
          document: LocalDocument(
            name: 'Exam notes.pdf',
            path: 'qa-exam.pdf',
            format: DocumentFormat.pdf,
            bytes: source,
          ),
          thumbnailKey: key,
        ),
      ),
    );
    final end = DateTime.now().add(const Duration(seconds: 40));
    while (DateTime.now().isBefore(end)) {
      await tester.pump(const Duration(milliseconds: 100));
      final icons = find.byWidgetPredicate(
        (w) => w is IconButton && w.tooltip == 'Bookmarks',
      );
      if (icons.evaluate().isNotEmpty &&
          tester.widget<IconButton>(icons).onPressed != null) {
        break;
      }
      await Future<void>.delayed(const Duration(milliseconds: 100));
    }
    expect(
      tester
          .widget<IconButton>(
            find.byWidgetPredicate(
              (w) => w is IconButton && w.tooltip == 'Bookmarks',
            ),
          )
          .onPressed,
      isNotNull,
    );
    await tester.tap(
      find.byWidgetPredicate(
        (w) => w is IconButton && w.tooltip == 'Bookmarks',
      ),
    );
    await tester.pumpAndSettle();
    await tester.tap(find.text('Bookmark page 1'));
    await tester.pumpAndSettle();
    expect(find.text('Page 1'), findsOneWidget);
    expect(await ReaderBookmarks.load(key), [1]);
    await tester.tap(find.text('Page 1'));
    await tester.pumpAndSettle();
    final cache = await getTemporaryDirectory();
    final preview = File('${cache.path}/thumbnails/$key.png');
    final until = DateTime.now().add(const Duration(seconds: 10));
    while (!await preview.exists() && DateTime.now().isBefore(until)) {
      await Future<void>.delayed(const Duration(milliseconds: 100));
      await tester.pump();
    }
    expect(await preview.exists(), isTrue);
    expect((await preview.readAsBytes()).take(4), [137, 80, 78, 71]);
    await tester.pumpWidget(
      const MaterialApp(home: Scaffold(body: Text('Cache safety check'))),
    );
    await tester.pumpAndSettle();
    final support = await getApplicationSupportDirectory();
    final original = File('${support.path}/documents/qa-original.txt');
    await original.parent.create(recursive: true);
    await original.writeAsString('original must survive');
    final derived = File('${cache.path}/slide-pdf/qa-converted.pdf');
    await derived.parent.create(recursive: true);
    await derived.writeAsBytes(source);
    final prefs = await SharedPreferences.getInstance();
    await prefs.setBool('qa-favorite', true);
    final result = await DocumentThumbnails.clearCache();
    expect((result['freed'] as num) > 0, isTrue);
    expect(await derived.exists(), isFalse);
    expect(await preview.exists(), isFalse);
    expect(await original.readAsString(), 'original must survive');
    expect(await ReaderBookmarks.load(key), [1]);
    expect(prefs.getBool('qa-favorite'), isTrue);
    await original.delete();
    debugPrint(
      'READER_FEATURES_PASS: real PDF bookmark, PNG thumbnail and originals-preserving native cache cleanup',
    );
  }, timeout: const Timeout(Duration(minutes: 2)));
  testWidgets('final Android Library Favorites and Settings screenshots', (
    tester,
  ) async {
    final dir = Directory(
      '${(await getApplicationSupportDirectory()).path}/documents/qa-ui',
    );
    await dir.create(recursive: true);
    final fixtures = <String, String>{
      'pdf': '',
      'docx': '',
      'pptx': '',
    };
    final docs = <LocalDocument>[];
    for (final item in {
      'Revision notes.pdf': DocumentFormat.pdf,
      'Exam slides.pptx': DocumentFormat.pptx,
      'Study plan.docx': DocumentFormat.docx,
      'Past questions.pdf': DocumentFormat.pdf,
      'Class handout.pdf': DocumentFormat.pdf,
    }.entries) {
      final bytes = base64Decode(fixtures[item.value.name]!);
      final file = File('${dir.path}/${item.key}');
      await file.writeAsBytes(bytes);
      docs.add(
        LocalDocument(
          name: item.key,
          path: file.path,
          format: item.value,
          size: bytes.length,
          favorite: docs.length < 2,
        ),
      );
    }
    await DocumentRepository().save(docs);
    await (await SharedPreferences.getInstance()).setBool(
      'storageIntroSeen',
      true,
    );
    await tester.pumpWidget(const app.OpenDocsApp());
    await tester.pumpAndSettle();
    await Future<void>.delayed(const Duration(milliseconds: 800));
    await tester.pumpAndSettle();
    await binding.convertFlutterSurfaceToImage();
    await tester.pumpAndSettle();
    final out = Directory('${(await getTemporaryDirectory()).path}/qa-ui');
    await out.create(recursive: true);
    for (final screen in ['library', 'favorites', 'settings']) {
      if (screen != 'library') {
        await tester.tap(
          find.text(screen == 'favorites' ? 'Favorites' : 'Settings').last,
        );
        await tester.pumpAndSettle();
      }
      expect(tester.takeException(), isNull);
      final bytes = await binding.takeScreenshot('opendocs-$screen');
      await File('${out.path}/$screen.png').writeAsBytes(bytes, flush: true);
    }
    debugPrint('FINAL_UI_SHOTS_READY ${out.path}');
      await Future<void>.delayed(const Duration(seconds: 3));
  }, timeout: const Timeout(Duration(minutes: 2)));
}
